-- Katalog klasických Mercedesů (řada, model, typové číslo, roky výroby, motor) – podklad pro formulář vozidla a statistiku dílů.
-- Sestaveno z Wikipedie (de/en) a katalogu dílů 30.10.2026; řádky „overeno = false“ ke kontrole.
-- Jedno typové číslo může mít víc řádků (změna motoru během výroby, např. 123.033 280 E: M110.984 → M110.988).
create table if not exists public.katalog_vozu (
  id serial primary key,
  typ text not null,               -- typové číslo, např. 126.024
  rada text not null,              -- W126, C126, R107…
  karoserie text,
  model text not null,             -- 300 SE
  od int not null, "do" int,       -- roky výroby
  motor text,                      -- M103
  motor_popis text,
  objem_ccm int, palivo text, vykon_kw int,
  poznamka text,
  overeno boolean not null default true
);
create index if not exists katalog_vozu_typ on public.katalog_vozu (typ);
alter table public.katalog_vozu enable row level security;
create policy dilna_cte on public.katalog_vozu for select to authenticated using ((select soukrome.je_clen()));
create policy majitel_meni on public.katalog_vozu for all to authenticated using ((select soukrome.je_majitel())) with check ((select soukrome.je_majitel()));

delete from public.katalog_vozu;
